import java.util.*;

public class Main {
    public static void main(String[] args) {
        String s = new Scanner(System.in).next();
        long table = 0, answer = 0; // coins on the table / coins already won
        for (char e : s.toCharArray()) {
            if (e == 'i') table++;
            else if (e == 'd') table = Math.max(0, table - 1);
            else { answer += table; table = 0; }
        }
        System.out.println(answer);
    }
}

package main

import "fmt"

func main() {
	var s string
	fmt.Scan(&s)
	table, answer := 0, 0 // coins on the table / coins already won
	for _, e := range s {
		switch e {
		case 'i':
			table++
		case 'd':
			table = max(0, table-1)
		default:
			answer += table
			table = 0
		}
	}
	fmt.Println(answer)
}
